def verify(res):
    W = 5
    P = 24
    G = 8
    S = 3
    if len(res) != W * P:
        return False

    pairs = set()
    for w in range(W):
        groups = [[] for _ in range(G)]
        for p in range(P):
            g = res[w * P + p]
            groups[g].append(p)

        for g in range(G):
            if len(groups[g]) != S:
                print(f"Week {w} group {g} has {len(groups[g])} players")
                return False
            for i in range(S):
                for j in range(i + 1, S):
                    p1, p2 = groups[g][i], groups[g][j]
                    if p1 > p2:
                        p1, p2 = p2, p1
                    if (p1, p2) in pairs:
                        print(f"Pair {p1}, {p2} repeated")
                        return False
                    pairs.add((p1, p2))
    return True

